    states = {(0,) * n: 0}
    for u, v, low, high, cost in edges:
        nxt = {}
        for balance, value in states.items():
            for flow in range(low, high + 1):
                b = list(balance)
                b[u] += flow
                b[v] -= flow
                key = tuple(b)
                val = value + flow * cost
